FoamFile { version 2.0; format ascii; class dictionary; location "system"; object controlDict; }
application simpleFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 2000;
deltaT 1;
writeControl timeStep;
writeInterval 200;
purgeWrite 2;
writeFormat ascii;
writePrecision 6;
writeCompression off;
timeFormat general;
timePrecision 6;
runTimeModifiable true;

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object controlDict; }
application simpleFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 2000;
deltaT 1;
writeControl timeStep;
writeInterval 200;
purgeWrite 2;
writeFormat ascii;
writePrecision 6;
writeCompression off;
timeFormat general;
timePrecision 6;
runTimeModifiable true;

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSchemes; }
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; div(phi,U) bounded Gauss linearUpwind grad(U); div(phi,k) bounded Gauss upwind; div(phi,omega) bounded Gauss upwind; div((nuEff*dev2(T(grad(U))))) Gauss linear; }
laplacianSchemes { default Gauss linear corrected 0.5; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected 0.5; }
wallDist { method meshWave; }

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSolution; }
solvers
{
    p { solver PCG; preconditioner DIC; tolerance 1e-6; relTol 0.05; }
    pFinal { $p; relTol 0; }
    U { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0.1; }
    k { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0.1; }
    omega { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0.1; }
}
SIMPLE
{
    nNonOrthogonalCorrectors 2;
    pRefCell 0;
    pRefValue 0;
    residualControl
    {
        p 1e-4;
        U 1e-4;
        k 1e-3;
        omega 1e-3;
    }
}
potentialFlow
{
    nNonOrthogonalCorrectors 3;
}
relaxationFactors
{
    fields
    {
        p 0.3;
    }
    equations
    {
        U 0.7;
        k 0.7;
        omega 0.7;
    }
}

FoamFile { version 2.0; format ascii; class dictionary; location "constant"; object momentumTransport; }
simulationType RAS;
RAS
{
    RASModel kOmegaSST;
    turbulence on;
    printCoeffs on;
    alphaK1 0.85;
    alphaK2 1.0;
    alphaOmega1 0.5;
    alphaOmega2 0.856;
    beta1 0.075;
    beta2 0.0828;
    betaStar 0.09;
    gamma1 0.5555;
    gamma2 0.44;
    a1 0.31;
    b1 1.0;
    c1 10.0;
    F3 false;
}

FoamFile { version 2.0; format ascii; class dictionary; location "constant"; object physicalProperties; }
transportModel Newtonian;
nu [0 2 -1 0 0 0 0] 1.516e-05;

FoamFile { version 2.0; format ascii; class volScalarField; location "0"; object k; }
#include "include/initialConditions"
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0.375;
boundaryField
{
    lid
    {
        type kqRWallFunction;
        value uniform 0.375;
    }
    fixedWalls
    {
        type inletOutlet;
        inletValue uniform 0.375;
        value uniform 0.375;
    }
}

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object controlDict; }
application icoFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 0.5;
deltaT 0.001;
writeControl adjustableRunTime;
writeInterval 0.05;
purgeWrite 2;
writeFormat ascii;
writePrecision 6;
writeCompression off;
timeFormat general;
timePrecision 6;
runTimeModifiable true;

